#[test]
fn new_and_convert_to_match_named_methods() {
    let v = 1234.5;
    assert_eq!(
        ElectricAdmittance::new(v, ElectricAdmittanceUnit::Siemens),
        ElectricAdmittance::from_siemens(v)
    );
    assert_eq!(
        ElectricAdmittance::from_base(v).convert_to(ElectricAdmittanceUnit::Siemens),
        ElectricAdmittance::from_base(v).as_siemens()
    );
    assert_eq!(
        ElectricAdmittance::new(v, ElectricAdmittanceUnit::Nanosiemens),
        ElectricAdmittance::from_nanosiemens(v)
    );
    assert_eq!(
        ElectricAdmittance::from_base(v).convert_to(ElectricAdmittanceUnit::Nanosiemens),
        ElectricAdmittance::from_base(v).as_nanosiemens()
    );
    assert_eq!(
        ElectricAdmittance::new(v, ElectricAdmittanceUnit::Microsiemens),
        ElectricAdmittance::from_microsiemens(v)
    );
    assert_eq!(
        ElectricAdmittance::from_base(v).convert_to(ElectricAdmittanceUnit::Microsiemens),
        ElectricAdmittance::from_base(v).as_microsiemens()
    );
    assert_eq!(
        ElectricAdmittance::new(v, ElectricAdmittanceUnit::Millisiemens),
        ElectricAdmittance::from_millisiemens(v)
    );
    assert_eq!(
        ElectricAdmittance::from_base(v).convert_to(ElectricAdmittanceUnit::Millisiemens),
        ElectricAdmittance::from_base(v).as_millisiemens()
    );
    assert_eq!(
        ElectricAdmittance::new(v, ElectricAdmittanceUnit::Kilosiemens),
        ElectricAdmittance::from_kilosiemens(v)
    );
    assert_eq!(
        ElectricAdmittance::from_base(v).convert_to(ElectricAdmittanceUnit::Kilosiemens),
        ElectricAdmittance::from_base(v).as_kilosiemens()
    );
    assert_eq!(
        ElectricAdmittance::new(v, ElectricAdmittanceUnit::Megasiemens),
        ElectricAdmittance::from_megasiemens(v)
    );
    assert_eq!(
        ElectricAdmittance::from_base(v).convert_to(ElectricAdmittanceUnit::Megasiemens),
        ElectricAdmittance::from_base(v).as_megasiemens()
    );
    assert_eq!(
        ElectricAdmittance::new(v, ElectricAdmittanceUnit::Gigasiemens),
        ElectricAdmittance::from_gigasiemens(v)
    );
    assert_eq!(
        ElectricAdmittance::from_base(v).convert_to(ElectricAdmittanceUnit::Gigasiemens),
        ElectricAdmittance::from_base(v).as_gigasiemens()
    );
    assert_eq!(
        ElectricAdmittance::new(v, ElectricAdmittanceUnit::Terasiemens),
        ElectricAdmittance::from_terasiemens(v)
    );
    assert_eq!(
        ElectricAdmittance::from_base(v).convert_to(ElectricAdmittanceUnit::Terasiemens),
        ElectricAdmittance::from_base(v).as_terasiemens()
    );
    assert_eq!(
        ElectricAdmittance::new(v, ElectricAdmittanceUnit::Mho),
        ElectricAdmittance::from_mhos(v)
    );
    assert_eq!(
        ElectricAdmittance::from_base(v).convert_to(ElectricAdmittanceUnit::Mho),
        ElectricAdmittance::from_base(v).as_mhos()
    );
    assert_eq!(
        ElectricAdmittance::new(v, ElectricAdmittanceUnit::Nanomho),
        ElectricAdmittance::from_nanomhos(v)
    );
    assert_eq!(
        ElectricAdmittance::from_base(v).convert_to(ElectricAdmittanceUnit::Nanomho),
        ElectricAdmittance::from_base(v).as_nanomhos()
    );
    assert_eq!(
        ElectricAdmittance::new(v, ElectricAdmittanceUnit::Micromho),
        ElectricAdmittance::from_micromhos(v)
    );
    assert_eq!(
        ElectricAdmittance::from_base(v).convert_to(ElectricAdmittanceUnit::Micromho),
        ElectricAdmittance::from_base(v).as_micromhos()
    );
    assert_eq!(
        ElectricAdmittance::new(v, ElectricAdmittanceUnit::Millimho),
        ElectricAdmittance::from_millimhos(v)
    );
    assert_eq!(
        ElectricAdmittance::from_base(v).convert_to(ElectricAdmittanceUnit::Millimho),
        ElectricAdmittance::from_base(v).as_millimhos()
    );
    assert_eq!(
        ElectricAdmittance::new(v, ElectricAdmittanceUnit::Kilomho),
        ElectricAdmittance::from_kilomhos(v)
    );
    assert_eq!(
        ElectricAdmittance::from_base(v).convert_to(ElectricAdmittanceUnit::Kilomho),
        ElectricAdmittance::from_base(v).as_kilomhos()
    );
    assert_eq!(
        ElectricAdmittance::new(v, ElectricAdmittanceUnit::Megamho),
        ElectricAdmittance::from_megamhos(v)
    );
    assert_eq!(
        ElectricAdmittance::from_base(v).convert_to(ElectricAdmittanceUnit::Megamho),
        ElectricAdmittance::from_base(v).as_megamhos()
    );
    assert_eq!(
        ElectricAdmittance::new(v, ElectricAdmittanceUnit::Gigamho),
        ElectricAdmittance::from_gigamhos(v)
    );
    assert_eq!(
        ElectricAdmittance::from_base(v).convert_to(ElectricAdmittanceUnit::Gigamho),
        ElectricAdmittance::from_base(v).as_gigamhos()
    );
    assert_eq!(
        ElectricAdmittance::new(v, ElectricAdmittanceUnit::Teramho),
        ElectricAdmittance::from_teramhos(v)
    );
    assert_eq!(
        ElectricAdmittance::from_base(v).convert_to(ElectricAdmittanceUnit::Teramho),
        ElectricAdmittance::from_base(v).as_teramhos()
    );
}

#[test]
fn in_unit_and_auto_unit_round_trip() {
    for v in [1e-9, 0.5, 1.0, 1234.5, 1e7, -3e4] {
        let q = ElectricAdmittance::from_base(v);
        let auto = q.auto_unit();
        assert_close(
            ElectricAdmittance::new(auto.value, auto.unit).as_base(),
            v,
            F64_TOL,
        );
        for &unit in ElectricAdmittanceUnit::ALL {
            let shown = q.in_unit(unit);
            assert_eq!((shown.value, shown.unit), (q.convert_to(unit), unit));
        }
    }
    assert_eq!(
        ElectricAdmittance::from_base(0.0).auto_unit().unit,
        ElectricAdmittanceUnit::Siemens
    );
}

